106	    /**
107	     * Find a role by its name and guard name.
108	     *
109	     * @return RoleContract|Role
110	     *
111	     * @throws RoleDoesNotExist
112	     */
113	    public static function findByName(string $name, ?string $guardName = null): RoleContract
114	    {
115	        $guardName ??= Guard::getDefaultName(static::class);
116	
117	        $role = static::findByParam(['name' => $name, 'guard_name' => $guardName]);
118	
119	        if (! $role) {
120	            throw RoleDoesNotExist::named($name, $guardName);
121	        }
122	
123	        return $role;
124	    }
125	
126	    /**
127	     * Find a role by its id (and optionally guardName).
128	     *
129	     * @return RoleContract|Role
130	     */
131	    public static function findById(int|string $id, ?string $guardName = null): RoleContract
132	    {
133	        $guardName ??= Guard::getDefaultName(static::class);
134	
135	        $role = static::findByParam([(new static)->getKeyName() => $id, 'guard_name' => $guardName]);
136	
137	        if (! $role) {
138	            throw RoleDoesNotExist::withId($id, $guardName);
139	        }
140	
141	        return $role;
142	    }
143	
144	    /**
145	     * Find or create role by its name (and optionally guardName).
146	     *
147	     * @return RoleContract|Role
148	     */
149	    public static function findOrCreate(string $name, ?string $guardName = null): RoleContract
150	    {
151	        $guardName ??= Guard::getDefaultName(static::class);
152	
153	        $attributes = ['name' => $name, 'guard_name' => $guardName];
154	
155	        $role = static::findByParam($attributes);
156	
157	        if (! $role) {
158	            $registrar = app(PermissionRegistrar::class);
159	            if ($registrar->teams) {
160	                $teamsKey = $registrar->teamsKey;
161	                $attributes[$teamsKey] = getPermissionsTeamId();
162	            }
163	
164	            return static::query()->create($attributes);
165	        }
166	
167	        return $role;
168	    }
169	
170	    /**
171	     * Finds a role based on an array of parameters.
172	     *
173	     * @return RoleContract|Role|null
174	     */
175	    protected static function findByParam(array $params = []): ?RoleContract
176	    {
177	        $query = static::query();
178	
179	        $registrar = app(PermissionRegistrar::class);
180	
181	        if ($registrar->teams) {
182	            $teamsKey = $registrar->teamsKey;
183	
184	            $query->where(fn ($q) => $q->whereNull($teamsKey)
185	                ->orWhere($teamsKey, $params[$teamsKey] ?? getPermissionsTeamId())
186	            );
187	            unset($params[$teamsKey]);
188	        }
189	
190	        foreach ($params as $key => $value) {
191	            $query->where($key, $value);
192	        }
193	
194	        return $query->first();
195	    }
196	
197	    /**
198	     * Determine if the role may perform the given permission.
199	     *
200	     * @param  string|int|\Spatie\Permission\Contracts\Permission|BackedEnum  $permission
201	     *
202	     * @throws PermissionDoesNotExist|GuardDoesNotMatch
203	     */
204	    public function hasPermissionTo($permission, ?string $guardName = null): bool
205	    {
206	        if ($this->getWildcardClass()) {
207	            return $this->hasWildcardPermission($permission, $guardName);
208	        }
209	
210	        $permission = $this->filterPermission($permission, $guardName);
211	
212	        if (! $this->getGuardNames()->contains($permission->guard_name)) {
213	            throw GuardDoesNotMatch::create($permission->guard_name, $guardName ? collect([$guardName]) : $this->getGuardNames());
214	        }
215	
216	        return $this->loadMissing('permissions')->permissions
217	            ->contains($permission->getKeyName(), $permission->getKey());
218	    }
219	}
